current_day = get_current_day()
events = search_calendar_events(query="Yoga Class", date=None)

if not events:
    print("No Yoga Classes found.")
else:
    start_of_today = datetime.fromisoformat(current_day + "T00:00:00")
    future_events = [e for e in events if e.start_time > start_of_today]

    if not future_events:
        print("No upcoming Yoga Classes found.")
    else:
        next_event = future_events[0]
        for event in future_events[1:]:
            if event.start_time < next_event.start_time:
                next_event = event
        print(next_event.start_time.strftime("%Y-%m-%d %H:%M"))
